32.3 Handling Python objects and errors
One can also handle more complex data, e.g. Python objects like lists. The attributes are
accessed with the extract function executed on the objects ”attr” function output. We can
also throw errors by telling the library that an error has occurred and returning. In the
following case, we have written a C++ function called ”afunction” which we want to call.
The function takes an integer N and a vector of length N as input, we have to convert the
python list to a vector of strings before calling the function.
#include <vector>
using namespace std;
void _afunction_wrapper(int N, boost::python::list mapping) {
int mapping_length = boost::python::extract<int>(mapping.attr("__len__")());
//Do Error checking, the mapping needs to be at least as long as N
if (mapping_length < N) {
PyErr_SetString(PyExc_ValueError,
"The string mapping must be at least of length N");
boost::python::throw_error_already_set();
return;
}

PyErr_SetString(PyExc_ValueError,
"The string mapping must be at least of length N");
boost::python::throw_error_already_set();
return;
}
vector<string> mystrings(mapping_length);
for (int i=0; i<mapping_length; i++) {
mystrings[i] = boost::python::extract<char const *>(mapping[i]);
}
//now call our C++ function
_afunction(N, mystrings);
}
using namespace boost::python;
BOOST_PYTHON_MODULE(c_afunction)
{
def("afunction", _afunction_wrapper);
}
